CREATE TABLE el_profile_photos(org_id TEXT NOT NULL REFERENCES el_organizations(id),entity TEXT NOT NULL CHECK(entity IN ('students','teachers','employees')),record_id TEXT NOT NULL,version TEXT NOT NULL,mime TEXT NOT NULL CHECK(mime IN ('image/png','image/jpeg')),byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 1 AND 32768),iv TEXT NOT NULL,ciphertext TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(org_id,entity,record_id),FOREIGN KEY(org_id,updated_by) REFERENCES el_memberships(org_id,user_id));
CREATE TRIGGER el_profile_photo_insert BEFORE INSERT ON el_profile_photos BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_profile_photos WHERE org_id=NEW.org_id AND entity=NEW.entity AND record_id=NEW.record_id) AND (SELECT count(*) FROM el_profile_photos WHERE org_id=NEW.org_id)>=100 THEN RAISE(ABORT,'Profile photo store limit is 100 per organization') END;
 SELECT CASE WHEN (NEW.entity='students' AND NOT EXISTS(SELECT 1 FROM el_students WHERE org_id=NEW.org_id AND id=NEW.record_id)) OR (NEW.entity='teachers' AND NOT EXISTS(SELECT 1 FROM el_teachers WHERE org_id=NEW.org_id AND id=NEW.record_id)) OR (NEW.entity='employees' AND NOT EXISTS(SELECT 1 FROM el_employees WHERE org_id=NEW.org_id AND id=NEW.record_id)) THEN RAISE(ABORT,'Profile photo record not found') END;
END;
CREATE TRIGGER el_profile_photo_identity BEFORE UPDATE ON el_profile_photos WHEN NEW.org_id<>OLD.org_id OR NEW.entity<>OLD.entity OR NEW.record_id<>OLD.record_id BEGIN SELECT RAISE(ABORT,'Profile photo identity is immutable'); END;
CREATE TRIGGER el_student_photo_cleanup AFTER DELETE ON el_students BEGIN DELETE FROM el_profile_photos WHERE org_id=OLD.org_id AND entity='students' AND record_id=OLD.id; END;
CREATE TRIGGER el_teacher_photo_cleanup AFTER DELETE ON el_teachers BEGIN DELETE FROM el_profile_photos WHERE org_id=OLD.org_id AND entity='teachers' AND record_id=OLD.id; END;
CREATE TRIGGER el_employee_photo_cleanup AFTER DELETE ON el_employees BEGIN DELETE FROM el_profile_photos WHERE org_id=OLD.org_id AND entity='employees' AND record_id=OLD.id; END;
